const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '自由落体（示意）' },
      { kind: 'text', payload: '静止释放' },
      { kind: 'text', payload: 'v' },
      { kind: 'text', payload: 'g' },
      { kind: 'text', payload: 'v、g 均竖直向下' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cx = w * 0.5;
    var ballR = Math.max(18, Math.min(w, h) * 0.06);
    var ballY = h * 0.22;
    var groundY = h * 0.88;

    function downArrow(x, y1, y2) {
      var len = y2 - y1;
      var headH = Math.min(16, Math.max(8, len * 0.12));
      var headW = headH * 0.7;
      return [
        ['M', x, y1],
        ['L', x, y2 - headH],
        ['M', x - headW, y2 - headH],
        ['L', x, y2],
        ['L', x + headW, y2 - headH],
        ['Z']
      ];
    }

    var ground = [['M', w * 0.12, groundY], ['L', w * 0.88, groundY]];
    var hatch = [];
    var i;
    for (i = 0; i < 9; i++) {
      var hx = w * 0.16 + i * (w * 0.68 / 8);
      hatch.push(['M', hx, groundY]);
      hatch.push(['L', hx - 10, groundY + 12]);
    }

    var ball = visualSdk.circle(cx, ballY, ballR);
    var vX = cx - Math.max(10, ballR * 0.35);
    var gX = cx + Math.max(10, ballR * 0.35);
    var arrowStartY = ballY + ballR - 4;
    var vEndY = arrowStartY + (groundY - arrowStartY) * 0.72;
    var gEndY = arrowStartY + (groundY - arrowStartY) * 0.55;
    var vArrow = downArrow(vX, arrowStartY, vEndY);
    var gArrow = downArrow(gX, arrowStartY, gEndY);

    return {
      schemaVersion: 1,
      sceneId: 'free-fall',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'ground', commands: ground },
        { id: 'hatch', commands: hatch },
        { id: 'ball', commands: ball },
        { id: 'v-arrow', commands: vArrow },
        { id: 'g-arrow', commands: gArrow }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ground', fill: '#6B7280', stroke: { width: 3 } },
          { type: 'path', pathId: 'hatch', fill: '#9CA3AF', stroke: { width: 2 } },
          { type: 'path', pathId: 'ball', fill: '#3B82F6', stroke: { width: 2 } },
          { type: 'path', pathId: 'v-arrow', fill: '#DC2626', stroke: { width: 3, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'g-arrow', fill: '#0F766E', stroke: { width: 3, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: cx, y: h * 0.08 }, hAlign: 'center', vAlign: 'middle', color: '#1F2937' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx + ballR + 16, y: ballY - ballR * 0.75 }, hAlign: 'left', vAlign: 'middle', color: '#1F2937' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: vX - 14, y: (arrowStartY + vEndY) / 2 }, hAlign: 'right', vAlign: 'middle', color: '#DC2626' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: gX + 14, y: (arrowStartY + gEndY) / 2 }, hAlign: 'left', vAlign: 'middle', color: '#0F766E' },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: cx, y: groundY - 16 }, hAlign: 'center', vAlign: 'bottom', color: '#1F2937' }
        ]
      }
    };
  }
};
